<script setup lang="ts">
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { onMounted, onUnmounted, ref, onBeforeUpdate } from "vue";

gsap.registerPlugin(ScrollTrigger);

const auto: ref<Boolean> = ref(false);
const partnership: { company: string, icon: string }[] = [
    {
        company: "PG",
        icon: "data:image/png;base64,"
    },
    {
        company: "BBIN",
        icon: "data:image/png;base64,"
    },
    {
        company: "SW",
        icon: "data:image/png;base64,"
    },
    {
        company: "KY 開元",
        icon: "data:image/png;base64,"
    },
    {
        company: "大滿貫",
        icon: "data:image/png;base64,"
    },
    {
        company: "波音体育",
        icon: "data:image/png;base64,"
    },
    {
        company: "NETENT",
        icon: "data:image/png;base64,"
    }
];
const partnershipClone: { company: string, icon: string }[] = partnership.concat(partnership);

const verticalContainer = ref<HTMLDivElement | null >(null);
const partnershipEl = ref<HTMLDivElement[]>([]);
let ctx: gsap.Context;

// 在每次更新前清空 refs 陣列，以避免在重新渲染時重複添加
onBeforeUpdate(() => {
    partnershipEl.value = [];
});

onMounted(() => {
    // 使用 gsap.context() 來包裹所有 GSAP 相關的程式碼
    ctx = gsap.context((self) => {
        // 確保 verticalContainer.value 存在
        if (!verticalContainer.value) return;
        const container = verticalContainer.value;

        // 2. 創建一個 ScrollTrigger 來處理滾動位置的“環繞”
        ScrollTrigger.create({
            start: 0,
            end: 'max',
            scroller: container,
            onLeave: (self) => {
                console.log("onLeave", self.scroll());
                self.scroll(1);
                ScrollTrigger.update();
            },
            onLeaveBack: self => {
                const scroll = self.scroll();

                self.scroll(ScrollTrigger.maxScroll(verticalContainer.value) - 1);
                console.log("onLeaveBack", scroll);

                ScrollTrigger.update();
            },
            onUpdate: self => {
                const scroll = self.scroll();
                // if (scroll >= loopHeight) {
                //     self.scroll(scroll % loopHeight);
                // }
                // else if (scroll < 0 && self.direction < 0) {
                //     console.log("scroll", scroll + loopHeight);
                //
                //     self.scroll(scroll + loopHeight);
                // }
            }
        });
        const loopHeight = verticalContainer.value.scrollHeight;
        const tl = gsap.to(verticalContainer.value, {
            scrollTop: loopHeight,
            duration: 25, // 調整這個值來控制滾動速度，數字越大越慢
            ease: 'none',
            repeat: -1,
        });
        // tl.play();

        // 3. 為所有項目 (包括原始和複製的) 創建動畫
        const allLinks = gsap.utils.toArray<HTMLDivElement>('.partnership', container);
        allLinks.forEach((link) => {
            // 使用 .from() 和 'x' 屬性來實現滑入效果，避免了 scaleX 造成的變形
            gsap.from(link, {
                x: '200px',
                repeat: 1,
                yoyo: true,
                ease: "none",
                scrollTrigger: {
                    trigger: link,
                    scroller: container, // <-- 同樣為每個動畫指定滾動容器
                    start: "center bottom",
                    end:"center top",
                    markers:true,
                    scrub:true,
                }
            });
        });
    }, verticalContainer.value || undefined); // 將 context 範圍限定在 verticalContainer 內
});

onUnmounted(() => {
    // 在元件卸載時，清理所有在 context 中創建的 GSAP 動畫和觸發器
    ctx && ctx.revert();
});
</script>

<template>
    <div class="partnership-wrapper">
        <div class="vertical" ref="verticalContainer">
            <div
                v-for="(partner, index) in partnershipClone"
                :key="index"
                class="partnership"
                :ref="el => { if (el) partnershipEl.push(el as HTMLDivElement) }"
            >
                <div class="company-icon">
                    <img
                        :src="partner.icon"
                        alt=""
                    />
                </div>
                <span class="company-text">{{ partner.company }}</span>
            </div>
        </div>
    </div>
</template>

