            background: rgba(237, 30, 36, 0.1);
            border-radius: 20px 0 0 20px;
            img {
                height: 100%;
                width: 100%;
                object-fit: contain;
            }
        }

        .company-text {
            position: relative;
            z-index: 2;
            display: inline-block;
        }
    }
    &::-webkit-scrollbar {
        display: none;
    }
}
</style>
